mapper.select:
SELECT  FROM qs__auth__permission_group

  name = #{name}

ORDER BY ${orderBy}
LIMIT #{limit} OFFSET #{offset}

SELECT permission_group_id FROM qs__auth__permission_group_account WHERE account_id = #{accountId}
UNION
SELECT pgorg.permission_group_id
FROM qs__auth__permission_group_org pgorg
JOIN qs__auth__account_organization ao ON ao.org_id = pgorg.org_id
WHERE ao.account_id = #{accountId}
